('push-up','Push-Up','chest','{triceps,shoulders,core}','bodyweight','{home,gym}','beginner',true,'From a plank, lower the chest to just above the floor and press back up.','{"Body stays one straight line","Hands just outside shoulder width"}'),
('incline-push-up','Incline Push-Up','chest','{triceps,shoulders}','bodyweight','{home,gym}','beginner',true,'Hands elevated on a bench or step, perform a push-up. Easier than the floor version.','{"The higher the hands, the easier it is","Keep glutes squeezed"}'),
('decline-push-up','Decline Push-Up','chest','{shoulders,triceps}','bodyweight','{home,gym}','intermediate',true,'Feet elevated on a chair or step, perform a push-up. Shifts load to the upper chest.','{"Do not let hips sag","Control the descent"}'),
